samples.raw_completion:
// Large reservoir of water, flow rate controlled by sensors at 5-inch
// intervals. Flow rate is determined by the water level and the level
// previous to the last sensor change, as described in the problem
// description.
module TopModule(
  input  clk,
  input  reset,
  input  [2:0] s,
  output fr2,
  output fr1,
  output fr0,
  output dfr
);
  reg [2:0] level;
  reg [2:0] last_level;
  reg [1:0] state;
  reg [1:0] next_state;
  wire [1:0] next_level = level + 1'b1;
  wire [1:0] last_next_level = last_level + 1'b1;
  wire fr2_next = (state == 2'b00) ? 1'b0 :
                  (state == 2'b01) ? (s[2] ? 1'b0 : 1'b1) :
                  (state == 2'b10) ? (s[1] ? 1'b0 : 1'b1) :
                  (state == 2'b11) ? (s[0] ? 1'b0 : 1'b1);
  wire fr1_next = (state == 2'b00) ? 1'b0 :
                  (state == 2'b01) ? 1'b0 :
                  (state == 2'b10) ? (s[0] ? 1'b0 : 1'b1) :
                  (state == 2'b11) ? (s[0] ? 1'b0 : 1'b1);
  wire fr0_next = (state == 2'b00) ? 1'b0 :
                  (state == 2'b01) ? (s[0] ? 1'b0 : 1'b1) :
                  (state == 2'b10) ? (s[0] ? 1'b0 : 1'b1) :
                  (state == 2'b11) ? (s[0] ? 1'b0 : 1'b1);
  wire dfr_next = (last_level < level) && (fr2_next != fr2);
  always @(*) begin
    case (state)
      2'b00: next_state = 2'b01;
      2'b01: next_state = (s[2]) ? 2'b10 : 2'b00;
      2'b10: next_state = (s[1]) ? 2'b11 : 2'b01;
      2'b11: next_state = (s[0]) ? 2'b00 : 2'b10;
    endcase
  end
  always @(posedge clk) begin
    if (reset) begin
      level <= 3'b111;
      last_level <= 3'b111;
      state <= 2'b11;
      fr2 <= 1'b1;
      fr1 <= 1'b1;
      fr0 <= 1'b1;
      dfr <= 1'b1;
    end else begin
      level <= next_level;
      last_level <= level;
      state <= next_state;
      fr2 <= fr2_next;
      fr1 <= fr1_next;
      fr0 <= fr0_next;
      dfr <= dfr_next;
    end
  end
endmodule

