// Large reservior of water, flow rate determined by three sensors.
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] level;
    reg [2:0] next_level;
    reg [1:0] open_valves;
    reg [1:0] next_open_valves;
    reg [2:0] nominal_fr;
    reg [2:0] next_nominal_fr;
    wire [2:0] sensors_asserted;
    wire [2:0] next_sensors_asserted;

    // Determine which sensors are asserted for the current level.
    always @* begin
        case (level)
            3'd0: sensors_asserted = 3'b111;
            3'd1: sensors_asserted = 3'b110;
            3'd2: sensors_asserted = 3'b100;
            default: sensors_asserted = 3'b000;
        endcase
    end

    // Determine the next level and the flow rate to be opened.
    always @* begin
        next_level = level;
        next_open_valves = open_valves;
        next_nominal_fr = nominal_fr;
        if (s[2] && level != 3'd2) begin
            next_level = 3'd2;
            next_open_valves = 2'b00;
            next_nominal_fr = 3'd0;
        end else if (s[1] && level != 3'd1) begin
            next_level = 3'd1;
            next_open_valves = 2'b01;
            next_nominal_fr = 3'd1;
        end else if (s[0] && level != 3'd0) begin
            next_level = 3'd0;
            next_open_valves = 2'b11;
            next_nominal_fr = 3'd2;
        end
    end

    // Determine the state machine transitions and outputs.
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b11;
            level <= 3'd0;
            open_valves <= 2'b11;
            nominal_fr <= 3'd2;
        end else begin
            state <= next_state;
            level <= next_level;
            open_valves <= next_open_valves;
            nominal_fr <= next_nominal_fr;
        end
        case (state)
            2'b00: begin
                next_state = 2'b01;
                fr2 = 1'b0; fr1 = 1'b0; fr0 = 1'b0; dfr = 1'b0;
            end
            2'b01: begin
                next_state = 2'b10;
                fr2 = 1'b0; fr1 = 1'b0; fr0 = nominal_fr[0]; dfr = 1'b0;
            end
            2'b10: begin
                next_state = 2'b11;
                fr2 = 1'b0; fr1 = nominal_fr[1]; fr0 = nominal_fr[0]; dfr = 1'b0;
            end
            2'b11: begin
                next_state = 2'b00;
                fr2 = 1'b1; fr1 = 1'b1; fr0 = 1'b1; dfr = 1'b1;
            end
        endcase
    end
endmodule

