// Large reservior of water, flow rate determined by sensors
module TopModule(
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] level;
    reg [2:0] next_level;
    reg [1:0] fr;
    reg [1:0] next_fr;
    reg [2:0] sensors;
    reg [2:0] next_sensors;
    reg [1:0] dfr_pre;
    always @(*) begin
        case (state)
            2'b00: begin
                next_sensors = 3'b111;
                next_fr = 2'b11;
                if (level > 2) next_state = 2'b00;
                else if (level == 2) next_state = 2'b01;
                else next_state = 2'b10;
            end
            2'b01: begin
                next_sensors = 3'b110;
                next_fr = 2'b10;
                if (level > 1) next_state = 2'b01;
                else next_state = 2'b10;
            end
            2'b10: begin
                next_sensors = 3'b100;
                next_fr = 2'b01;
                next_state = 2'b10;
            end
        endcase
    end
    always @(*) begin
        case (level)
            3'b000: fr = 2'b11;
            3'b001: fr = 2'b10;
            3'b010: fr = 2'b01;
            3'b011: fr = 2'b00;
            3'b100: fr = 2'b00;
            3'b101: fr = 2'b00;
            3'b110: fr = 2'b00;
            3'b111: fr = 2'b00;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            level <= 3'b000;
            sensors <= 3'b111;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            state <= next_state;
            level <= next_level;
            sensors <= next_sensors;
            fr2 <= (sensors[2]) ? 1'b0 : fr[2];
            fr1 <= (sensors[1]) ? 1'b0 : fr[1];
            fr0 <= (sensors[0]) ? 1'b0 : fr[0];
            dfr <= (level > next_level) ? 1'b1 : 1'b0;
        end
    end
    always @(posedge clk) begin
        next_level <= level + 1'b1;
    end
endmodule

