module TopModule(
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);
    reg [2:0] level;
    reg [2:0] level_next;
    reg [2:0] level_prev;
    reg [1:0] state;
    reg [1:0] state_next;
    reg [2:0] fr;
    wire [2:0] fr_nom;
    wire [2:0] fr_inc;
    reg [2:0] fr_next;
    reg dfr_next;
    assign fr_nom = 3'b000 + level;
    assign fr_inc = (level > level_prev) ? (level_prev + 1'b1) : level;
    always @* begin
        case (state)
            2'b00: if (s[2]) level_next = 3'b000; else level_next = 3'b001;
            2'b01: if (s[1]) level_next = 3'b001; else level_next = 3'b010;
            2'b10: if (s[0]) level_next = 3'b010; else level_next = 3'b011;
            2'b11: level_next = 3'b011;
        endcase
    end
    always @* begin
        case (state)
            2'b00: state_next = 2'b01;
            2'b01: if (s[1]) state_next = 2'b10; else state_next = 2'b00;
            2'b10: if (s[0]) state_next = 2'b11; else state_next = 2'b01;
            2'b11: state_next = 2'b11;
        endcase
    end
    always @* begin
        case (state)
            2'b00: fr_next = fr_nom;
            2'b01: fr_next = (s[0]) ? fr_nom : fr_inc;
            2'b10: fr_next = (s[0]) ? fr_nom : fr_inc;
            2'b11: fr_next = fr_nom;
        endcase
    end
    always @* dfr_next = (level > level_prev);
    always @(posedge clk) begin
        if (reset) begin
            level <= 3'b000;
            state <= 2'b00;
            fr <= 3'b111;
            dfr <= 1'b1;
        end else begin
            level <= level_next;
            state <= state_next;
            fr <= fr_next;
            dfr <= dfr_next;
        end
    end
    assign fr2 = ~fr[2];
    assign fr1 = ~fr[1];
    assign fr0 = ~fr[0];
endmodule

