// State machine: the combinational next_state and output logic determine
// the flow rate.
reg [1:0] state, next_state;
reg [2:0] s;
reg fr2, fr1, fr0, dfr;
always @* begin
    case (state)
        2'b00: begin next_state = 2'b00; fr2 = 1; fr1 = 1; fr0 = 1; dfr = 1; end
        2'b01: begin next_state = 2'b01; fr2 = 0; fr1 = 1; fr0 = 1; dfr = 0; end
        2'b10: begin next_state = 2'b10; fr2 = 0; fr1 = 0; fr0 = 1; dfr = 0; end
        2'b11: begin next_state = 2'b11; fr2 = 0; fr1 = 0; fr0 = 0; dfr = 0; end
    endcase
end
always @(posedge clk) begin
    if (reset) state <= 2'b00;
    else state <= next_state;
end
// Level change detector: combinational signal s that indicates whether
// the water level has increased or decreased.
reg level_changed;
always @(posedge clk) begin
    if (reset) level_changed <= 1;
    else level_changed <= s[2] != s[1] || s[1] != s[0];
end
// Registered water level: the output of the state machine is registered
// to provide a stable reference point for the level change detector.
